147	/**
148	 * Formats a file size in bytes to a human-readable string
149	 */
150	export function formatFileSize(bytes: number): string {
151	  if (bytes === 0) {
152	    return '0 B';
153	  }
154	  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
155	  const i = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), units.length - 1);
156	  return `${(bytes / Math.pow(1024, i)).toFixed(i > 0 ? 1 : 0)} ${units[i]}`;
157	}
