55	/**
56	 * Prints a header with file information
57	 */
58	async function printLogHeader(logPath: string, isCurrentSession: boolean): Promise<void> {
59	  const stats = await fs.stat(logPath);
60	
61	  printBorder();
62	  logger.info(chalk.bold(path.basename(logPath)));
63	  logger.info(chalk.gray(`Path: ${logPath}`));
64	  logger.info(chalk.gray(`Size: ${formatFileSize(stats.size)}`));
65	  logger.info(chalk.gray(`Modified: ${stats.mtime.toLocaleString()}`));
66	
67	  if (isCurrentSession) {
68	    logger.info(chalk.yellow('Note: This is the log file for the current CLI session.'));
69	  }
